SELECT s0."rid_people_user" AS "$k0", s0."f_user_created_at" AS "created_at", s0."f_user_updated_at" AS "updated_at", s0."f_user_clerk_user_id" AS "clerk_user_id", s0."f_user_email" AS "email", s0."f_user_in_trial" AS "in_trial", s0."f_user_is_paying" AS "is_paying", s0."f_user_stripe_customer_id" AS "stripe_customer_id", s0."f_user_profession_updated" AS "profession_updated", s0."f_user_is_onboarded" AS "is_onboarded" FROM "tbl_people_user" AS s0 WHERE (s0."f_user_clerk_user_id" IN (SELECT value FROM json_each(:ids))) ORDER BY s0."rid_people_user" ASC
